// Package edition holds the members of the newest core edition the pinned upstream release
// supports. The table is generated by scripts/edition.sh.
package edition

// Kind of an edition member.
const (
	KindArray     = "array"
	KindLayout    = "layout"
	KindDType     = "dtype"
	KindAggregate = "aggregate"
)

// Member is one identifier a reader must know.
type Member struct {
	Kind  string
	ID    string
	Since string
}

// Members returns a copy of the table.
func Members() []Member {
	return append([]Member(nil), members...)
}

// Has reports whether the edition contains the identifier of that kind.
func Has(kind, id string) bool {
	for _, m := range members {
		if m.Kind == kind && m.ID == id {
			return true
		}
	}
	return false
}
